from taf.internal.gnb.oam.rap.client.rap.v2 import TOPOLOGYApi, ApiClient, Configuration
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class TopologyV1(object):

    def __init__(self, con_details, access_token):
        self.configuration = self._create_configuration_prepare(con_details)
        self.configuration.access_token = access_token
        self.topology_api_instance = TOPOLOGYApi(ApiClient(self.configuration))

    @staticmethod
    def _create_configuration_prepare(con_details):
        config_object = Configuration()
        config_object.host = con_details.make_configuration_host(original_endpoint=config_object.host)
        config_object.retries = 0
        config_object.verify_ssl = con_details.secure
        return config_object

    def get_unit_logical_info(self, uid):
        return self.topology_api_instance.topology_logical_details_uid_get(uid=uid)

    def get_unit_physical_info(self, uid):
        return self.topology_api_instance.topology_physical_details_uid_get(uid=uid)

    def get_site_logical_info(self):
        return self.topology_api_instance.topology_logical_get()

    def get_site_physical_info(self):
        return self.topology_api_instance.topology_physical_get()
